import{_ as t,l as i,o as e,c as n,v as o,p as s,x as l,d,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"Roofline 模型","description":"","frontmatter":{"title":"Roofline 模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/roofline-model.md","filePath":"cs/roofline-model.md","lastUpdated":1789023840000}'),f={name:"cs/roofline-model.md"};function p(h,a,A,E,_,u){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="roofline-模型" tabindex="-1">Roofline 模型 <a class="header-anchor" href="#roofline-模型" aria-label="Permalink to &quot;Roofline 模型&quot;">​</a></h1><div class="epigraph"><p>把核的峰值算力和内存带宽画成屋顶：内核的算术强度落在哪一侧，就决定你该减访存还是加 FLOP 实现，而不是盲目加核。</p><footer>—— 据 Williams, Waterman, and Patterson, Roofline: An Insightful Visual Performance Model, CACM 2009 整理</footer></div><p><a href="/cs/pmu-counters">上一课</a> 能读带宽与运算事件。<a href="/cs/gustafson-law">Gustafson</a> 不告诉你被哪堵墙挡住。本课不重讲采样。缺口是 <strong>Roofline：算术强度 \\(I = W/Q\\)（运算/字节）对照机器屋顶。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代码慢，有人加线程，有人展开循环。<a href="/cs/mlp-memory-parallelism">MLP</a> 提高的是延迟隐藏，屋顶仍可能是 DRAM 字节/秒。缺口不是再加一个 PMU 事件名，而是<strong>一张图：横轴强度，纵轴性能，斜线是带宽×强度，横线是峰值算力。</strong></p><p><span class="marginnote">Williams–Waterman–Patterson：屋顶随层次变（L1/L2/DRAM 多条斜线）。落在斜线上是带宽受限；横线上是计算受限。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测或查：\\(B\\) 为有效带宽（注意 <a href="/cs/multi-socket-interconnect">NUMA</a> 与 <a href="/cs/memory-coalescing">合并</a>），\\(F\\) 为峰值 FLOP/s（注意向量宽度与频率墙）。画 \\(P\\le \\min(F, B\\cdot I)\\)。把内核画成点；优化：提高 \\(I\\)（复用、blocking、<a href="/cs/systolic-array">脉动</a>）或提高有效 \\(B\\)（预取、合并、放对层次）。</p>',8)),(e(),s(m,null,{default:l(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%AE%97%E6%9C%AF%E5%BC%BA%E5%BA%A6%22%5D%20--%3E%20CMP%5B%22%E4%B8%8E%20F%2FB%20%E6%AF%94%E8%BE%83%22%5D%0A%20%20CMP%20--%3E%7C%22I%20%E5%B0%8F%22%7C%20BW%5B%22%E5%B8%A6%E5%AE%BD%E5%A2%99%EF%BC%9A%E5%87%8F%E6%90%AC%E7%A7%BB%22%5D%0A%20%20CMP%20--%3E%7C%22I%20%E5%A4%A7%22%7C%20COMP%5B%22%E8%AE%A1%E7%AE%97%E5%A2%99%EF%BC%9A%E5%90%91%E9%87%8F%E5%8C%96%20%2F%20%E4%B8%93%E7%94%A8%E5%8D%95%E5%85%83%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 Amdahl 正交：Amdahl 是串行比，Roofline 是已并行内核的强度。DSA 与 GPU 各有自己的屋顶。不要在这里画大模型训练的集群 Roofline 当本课主体。gem5 下一课可以输出用于画屋顶的计数，但模拟带宽要校准。</p><p>点落在屋顶之下：还有对齐、bank 冲突、<a href="/cs/warp-divergence">发散</a>、指令混合不是峰值 FMA。屋顶是上界，不是自动达到的工作点。先垂直爬到屋顶（微结构/向量化），再沿强度轴右移（算法 blocking）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把缓存带宽的每一条斜线标定到某 SKU。MTTF 与可靠性下一单元末才出现；Roofline 不管错误。模拟器用来解释「为何点落在屋顶下」（端口、对齐）。</p><p>后课默认：先判断墙，再改算法或微结构参数。gem5 给出可控的结构旋钮与统计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Roofline 用强度区分带宽墙与计算墙。</li><li>层次不同屋顶不同；NUMA 降低有效 \\(B\\)。</li><li>gem5 用模拟把结构旋钮变成可重复实验，下一课。</li><li>出处：Williams, Waterman, Patterson, <em>CACM</em>, 2009。</li></ul>',8))])}const C=t(f,[["render",p]]);export{P as __pageData,C as default};
